from django.contrib.postgres.search import SearchVector, SearchQuery, SearchRank
from django.db.models import Q


class BookListView(generics.ListAPIView):
    serializer_class = BookSerializer

    def get_queryset(self):
        qs = Book.objects.select_related("author")
        search = self.request.query_params.get("search")
        if not search:
            return qs

        vector = (
            SearchVector("title", weight="A") +
            SearchVector("description", weight="B") +
            SearchVector("author__full_name", weight="C")
        )
        query = SearchQuery(search, config="simple")

        return (
            qs.annotate(rank=SearchRank(vector, query))
              .filter(rank__gte=0.1)
              .order_by("-rank")
        )

class CaseSensitiveSearchFilter(filters.SearchFilter):
    """جستجوی حساس به حروف برای فیلدهای مشخص."""

    def construct_search(self, field_name):
        if field_name == "isbn":
            # برای ISBN، حساس به حروف
            return field_name
        # برای بقیه، از icontains
        return f"{field_name}__icontains"


class BookViewSet(viewsets.ModelViewSet):
    queryset = Book.objects.all()
    serializer_class = BookSerializer
    filter_backends = [CaseSensitiveSearchFilter]
    search_fields = ["title", "isbn"]

from django.db.models import Case, When, IntegerField, Value


class RankedSearchFilter(filters.BaseFilterBackend):
    def filter_queryset(self, request, queryset, view):
        search = request.query_params.get("search")
        if not search:
            return queryset

        return queryset.filter(
            Q(title__icontains=search) |
            Q(description__icontains=search)
        ).annotate(
            rank=Case(
                When(title__istartswith=search, then=Value(100)),
                When(title__icontains=search, then=Value(50)),
                When(description__icontains=search, then=Value(10)),
                default=Value(0),
                output_field=IntegerField(),
            )
        ).order_by("-rank", "-created_at")
